/**
 * A CA (Certificate Authority) certificate at the organization level. CA certificates are
 * the root of trust for all tenant certificates within the organization. Private keys for
 * signing CAs are encrypted with AES-256-GCM and stored separately; non-signing CAs only
 * store the public certificate.
 */
struct axiam_mgmt_ca_certificate {
    /**
     * The issuers above [`Self::public_cert_pem`], concatenated PEM, nearest issuer first
     * and the root last. `None` for a CA that is its own root, which is every CA AXIAM
     * generated before Vault's PKI engine was an option. Present for a `vault_pki` CA,
     * where it is the only copy of the root certificate anything outside Vault will ever
     * see — a relying party cannot validate an AXIAM-issued leaf without it, and
     * `root/generate/internal` returns it exactly once. Optional.
     */
    char *chain_pem;
    /**
     * The server's `created_at` field.
     */
    char *created_at;
    /**
     * SHA-256 fingerprint of the certificate.
     */
    char *fingerprint;
    /**
     * The server's `id` field.
     */
    char *id;
    /**
     * The server's `key_algorithm` field.
     */
    axiam_mgmt_key_algorithm_t key_algorithm;
    /**
     * Which custodian holds this CA's signing key. Recorded per CA rather than read from
     * configuration, so adopting a new custodian does not strand the CAs that already
     * exist. Not secret — an operator needs to see it, and it discloses only where a key is
     * kept. Optional.
     */
    char *key_custody;
    /**
     * Where the custodian put the key. A Vault path under its mount; `None` for database
     * custody, whose locator is the row itself. Optional.
     */
    char *key_locator;
    /**
     * Whether this CA is offered as a trust anchor for mutual TLS. When set, the server
     * exports this CA's **public** certificate to the bundle named by
     * `AXIAM__SERVER__TLS__CLIENT_CA_BUNDLE_PATH` at startup and turns client-certificate
     * authentication on (`optional`) if the operator has not configured it explicitly. A
     * client presenting a certificate that chains to this CA is then verified by the TLS
     * layer itself, which is what `axiam_pki::mtls` needs to authenticate an IoT device or
     * a service account by certificate rather than by secret. # What is and is not copied
     * Only `public_cert_pem` — the certificate. The **private key stays where its custodian
     * put it** (Vault, or sealed into the row) and is never written to the server volume. A
     * trust anchor is public by construction: it is what the server hands every client
     * during the TLS handshake, and every device that has to validate the chain already
     * holds a copy. # Why a restart rustls builds its `RootCertStore` once, when the
     * listener is constructed, and actix-web binds that config for the process's life.
     * Toggling this changes what the *next* boot trusts, and the API says so in its
     * response rather than pretending the change took effect. Defaults to `false`, so a
     * deployment that never touches this keeps exactly the TLS posture it has today.
     * Optional.
     */
    int mtls_trust_anchor;
    int has_mtls_trust_anchor; /**< 1 when `mtls_trust_anchor` is set. */
    /**
     * Validity end.
     */
    char *not_after;
    /**
     * Validity start.
     */
    char *not_before;
    /**
     * The organization this CA belongs to.
     */
    char *organization_id;
    /**
     * The CA in this organization that signed this one. `None` for an organization-level
     * CA, which is either self-signed or imported and has no parent inside AXIAM. Optional.
     */
    char *parent_ca_id;
    /**
     * PEM-encoded public certificate. The certificate that *signs*, which under `vault_pki`
     * custody is the intermediate rather than the root beneath which it was created.
     */
    char *public_cert_pem;
    /**
     * The server's `status` field.
     */
    axiam_mgmt_certificate_status_t status;
    /**
     * The CA's common name, e.g. `ACME Corp Root CA`. The normalised value: a `CN=` prefix
     * in the request is understood and stripped, so this always says what the certificate's
     * subject DN says (DF-023).
     */
    char *subject;
    /**
     * The tenant this CA signs for, when it is a tenant signing CA. `None` for an
     * organization-level CA — the trust anchor, and the only kind that existed before
     * tenant signing CAs. `Some` for an intermediate created under one, which exists so a
     * tenant's user, service and device certificates chain through a CA that can be revoked
     * and replaced without touching the anchor the rest of the estate trusts. Optional.
     */
    char *tenant_id;
};

